"use client";

import Link from "next/link";
import { useUser } from "@auth0/nextjs-auth0/client";
import styles from "./account.module.css";

/**
 * Log in / Sign up when signed out, the person's name and Log out when signed
 * in. Shows nothing while loading or if the session check fails.
 *
 * Sign up goes to the questions at /onboarding, which hand over to Auth0 at
 * the end. Pass showSignUp={false} on that page itself.
 *
 * The /auth links are plain <a> tags on purpose: they must be full page loads,
 * because those routes are served by Auth0 in proxy.ts and are not pages here.
 */
export function Account({ className = "", showSignUp = true }: { className?: string; showSignUp?: boolean }) {
  const { user, isLoading, error } = useUser();
  const ready = !isLoading && !error;

  return (
    <nav aria-label="Account" className={`${styles.account} ${className}`}>
      {ready && user && (
        <>
          <span className={styles.name}>{user.name || user.email}</span>
          <a className={styles.link} href="/auth/logout">
            Log out
          </a>
        </>
      )}
      {ready && !user && (
        <>
          <a className={styles.link} href="/auth/login">
            Log in
          </a>
          {showSignUp && (
            <Link className={styles.button} href="/onboarding">
              Sign up
            </Link>
          )}
        </>
      )}
    </nav>
  );
}
